"use client";

import * as React from "react";
import { Lock, RotateCw, Upload, X } from "lucide-react";
import { CopyButton } from "./copy-button";
import { Faces } from "./faces";
import { Input } from "./input";
import { NumberRoll } from "./number-roll";
import { SegmentedControl } from "./segmented-control";
import { StatusButton, type ActionStatus } from "./status-button";
import { Switch } from "./switch";
import { TextMorph } from "./text-morph";
import {
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * FILE SHARE: files that fold into one link
 *
 *   drop      the lit panel is the drop area; dragging files over
 *             it brightens its edge and says how many will land
 *   upload    each file uploads as soon as it's added, its row
 *             filling with a thin line and rolling its percent;
 *             a failed one offers Retry, a removed one is aborted
 *   options   how long the link lives, and an optional password
 *   link      Create link goes Creating → the rows fly up into the
 *             panel, which turns into the link card: the URL with
 *             Copy, what's in it, and the files fanned as a stack
 *
 * Storage is yours: onUpload sends one file (report progress and
 * honour the signal), onCreateLink makes the link from what your
 * uploads returned. Throw an Error and its message shows in place.
 * ───────────────────────────────────────────────────────── */

export interface FileShareUploadContext {
  /** Report progress from 0 to 1. */
  onProgress: (fraction: number) => void;
  /** Aborted when the file is removed. */
  signal: AbortSignal;
}

export interface FileShareFile {
  name: string;
  size: number;
  type: string;
  /** Whatever onUpload resolved with for this file, e.g. its storage key. */
  result: unknown;
}

export interface FileShareRequest {
  files: FileShareFile[];
  /** Days the link lives. */
  expiresIn: number;
  password?: string;
}

export interface FileShareHandle {
  /** Add files from anywhere: a paste handler, a button of your own. */
  add: (files: File[]) => void;
}

export interface FileShareProps {
  /** Upload one file; resolve with what you'll need to make the link (a key, an id). */
  onUpload: (file: File, context: FileShareUploadContext) => Promise<unknown>;
  /** Make the link; resolve with its URL. */
  onCreateLink: (share: FileShareRequest) => Promise<{ url: string }>;
  /** Native input syntax, e.g. "image/*,.pdf". */
  accept?: string;
  /** Bytes per file. */
  maxSize?: number;
  maxFiles?: number;
  /** Choices for how many days the link lives. */
  expiries?: number[];
  ref?: React.Ref<FileShareHandle>;
  className?: string;
}

type Item = {
  id: string;
  file: File;
  progress: number;
  status: "uploading" | "done" | "error";
  error?: string;
  result?: unknown;
  controller?: AbortController;
};

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const EXPIRIES = [1, 7, 30];
const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const LIT: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: `radial-gradient(120% 90% at 0% 0%, ${mix("var(--primary-foreground)", 22)} 0%, transparent 55%), linear-gradient(175deg, transparent 40%, ${mix("black", 24)} 100%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 36)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 12)}`,
};
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
const ACTION: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix("var(--primary-foreground)", 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix("var(--primary-foreground)", 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};

const extOf = (name: string) =>
  name.includes(".")
    ? name.split(".").pop()!.slice(0, 4).toUpperCase()
    : "FILE";
function tint(seed: string): React.CSSProperties {
  let h = 0;
  for (const c of seed) h = (h * 31 + c.charCodeAt(0)) >>> 0;
  const chart = `var(--chart-${(h % 5) + 1}, var(--primary))`;
  return {
    background: mix(chart, 20, "var(--card)"),
    color: mix(chart, 75, "var(--foreground)"),
    boxShadow: `inset 0 0 0 1px ${mix(chart, 26)}`,
  };
}
function size(bytes: number) {
  const units = ["B", "KB", "MB", "GB"];
  let n = bytes;
  let u = 0;
  while (n >= 1000 && u < units.length - 1) {
    n /= 1000;
    u++;
  }
  return `${n >= 10 || u === 0 ? Math.round(n) : n.toFixed(1)} ${units[u]}`;
}
let seq = 0;

export function FileShare({
  onUpload,
  onCreateLink,
  accept,
  maxSize,
  maxFiles = 20,
  expiries = EXPIRIES,
  ref,
  className = "",
}: FileShareProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const [items, setItems] = React.useState<Item[]>([]);
  const [over, setOver] = React.useState(0);
  const [expires, setExpires] = React.useState(
    expiries[Math.min(1, expiries.length - 1)] ?? 7,
  );
  const [lock, setLock] = React.useState(false);
  const [password, setPassword] = React.useState("");
  const [create, setCreate] = React.useState<{
    status: ActionStatus;
    error?: string;
  }>({ status: "idle" });
  const [link, setLink] = React.useState<{
    url: string;
    files: Item[];
    flown?: boolean;
  } | null>(null);
  // While the rows fly up, the list stops clipping so they can leave it.
  const [flying, setFlying] = React.useState(false);
  const [ready, setReady] = React.useState(false);
  const [said, setSaid] = React.useState("");
  const inputRef = React.useRef<HTMLInputElement>(null);
  const sectionRef = React.useRef<HTMLElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLUListElement>(null);
  const depth = React.useRef(0);

  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  const patch = (id: string, next: Partial<Item>) =>
    setItems((list) => list.map((i) => (i.id === id ? { ...i, ...next } : i)));

  const upload = (item: Item) => {
    const controller = new AbortController();
    patch(item.id, {
      status: "uploading",
      progress: 0,
      error: undefined,
      controller,
    });
    onUpload(item.file, {
      onProgress: (f) =>
        patch(item.id, { progress: Math.max(0, Math.min(1, f)) }),
      signal: controller.signal,
    })
      .then((result) => {
        if (!controller.signal.aborted)
          patch(item.id, { status: "done", progress: 1, result });
      })
      .catch((e) => {
        if (!controller.signal.aborted)
          patch(item.id, {
            status: "error",
            error:
              e instanceof Error && e.message ? e.message : "Upload failed",
          });
      });
  };

  const add = (files: FileList | File[]) => {
    if (link) return;
    const room = Math.max(0, maxFiles - items.length);
    const next: Item[] = [...files].slice(0, room).map((file) => ({
      id: `f${++seq}`,
      file,
      progress: 0,
      status: "uploading" as const,
    }));
    for (const item of next) {
      if (maxSize && item.file.size > maxSize) {
        item.status = "error";
        item.error = `Over ${size(maxSize)}`;
      }
    }
    setItems((list) => [...list, ...next]);
    setCreate({ status: "idle" });
    setSaid(`${next.length} ${next.length === 1 ? "file" : "files"} added.`);
    next.filter((i) => i.status !== "error").forEach(upload);
  };

  React.useImperativeHandle(ref, () => ({
    add: (files: File[]) => add(files),
  }));

  const remove = (item: Item) => {
    item.controller?.abort();
    setItems((list) => list.filter((i) => i.id !== item.id));
  };

  const doneItems = items.filter((i) => i.status === "done");
  const uploading = items.some((i) => i.status === "uploading");
  const total = items.reduce((n, i) => n + i.file.size, 0);
  const sent = items.reduce(
    (n, i) => n + i.file.size * (i.status === "done" ? 1 : i.progress),
    0,
  );
  const canCreate =
    doneItems.length > 0 && !uploading && (!lock || password.trim().length > 0);
  const busy = create.status === "pending" || create.status === "success";

  const createLink = async () => {
    if (!canCreate || busy) return;
    setCreate({ status: "pending" });
    try {
      const { url } = await onCreateLink({
        files: doneItems.map((i) => ({
          name: i.file.name,
          size: i.file.size,
          type: i.file.type,
          result: i.result,
        })),
        expiresIn: expires,
        password: lock && password.trim() ? password.trim() : undefined,
      });
      setCreate({ status: "success" });
      setSaid(`Link ready: ${url}`);
      // Each file's tile leaps into the corner where the link's stack appears and lands as one of its cards,
      // while the rows fold away; then the panel turns into the link under tiles already in place.
      const section = sectionRef.current;
      const panel = panelRef.current?.getBoundingClientRect();
      const rows = [
        ...(listRef.current?.querySelectorAll<HTMLElement>("[data-file]") ??
          []),
      ];
      const flights: HTMLElement[] = [];
      if (section && panel && rows.length && !reduced) {
        setFlying(true);
        const box = section.getBoundingClientRect();
        // Screen px to the block's own px, so the tiles land true inside a scaled or zoomed container too.
        const k = box.width / (section.offsetWidth || box.width) || 1;
        // The stack's centre on the link face: the panel's top-right corner, inside its padding.
        const fan = { x: panel.right - 54 * k, y: panel.top + 46 * k };
        const shown = rows.slice(0, 3);
        shown.forEach((row, i) => {
          row.animate(
            [
              { opacity: 1, transform: "none" },
              { opacity: 0, transform: "translateY(-6px)" },
            ],
            {
              duration: 260,
              delay: 120 + i * 90,
              easing: EASE,
              fill: "forwards",
            },
          );
          const tile = row.querySelector<HTMLElement>("[data-tile]");
          if (!tile) return;
          const r = tile.getBoundingClientRect();
          const copy = tile.cloneNode(true) as HTMLElement;
          Object.assign(copy.style, {
            position: "absolute",
            left: `${(r.left - box.left) / k}px`,
            top: `${(r.top - box.top) / k}px`,
            width: `${r.width / k}px`,
            height: `${r.height / k}px`,
            margin: "0",
            zIndex: "30",
            pointerEvents: "none",
            willChange: "transform",
          });
          section.appendChild(copy);
          flights.push(copy);
          const turn = (i - (shown.length - 1) / 2) * 10;
          const dx = (fan.x - (r.left + r.width / 2)) / k + turn * 0.6;
          const dy = (fan.y - (r.top + r.height / 2)) / k;
          const grow = 40 / (r.width / k);
          copy.animate(
            [
              { transform: "translate(0px, 0px) rotate(0deg) scale(1)" },
              {
                transform: `translate(${dx * 0.42}px, ${dy * 0.58 - 28}px) rotate(${turn * 0.5 - 6}deg) scale(${(1 + grow) / 2})`,
                offset: 0.55,
              },
              {
                transform: `translate(${dx}px, ${dy}px) rotate(${turn}deg) scale(${grow})`,
              },
            ],
            {
              duration: 640,
              delay: i * 90,
              easing: "cubic-bezier(0.45,0,0.2,1)",
              fill: "forwards",
            },
          );
        });
      }
      const landed =
        reduced || !flights.length ? 300 : 560 + (flights.length - 1) * 90;
      window.setTimeout(() => {
        setLink({ url, files: doneItems, flown: flights.length > 0 });
        setFlying(false);
        // The real stack is under the flown tiles now; they hand over and go.
        flights.forEach(
          (f) =>
            (f.animate([{ opacity: 1 }, { opacity: 0 }], {
              duration: 220,
              delay: 260,
              fill: "forwards",
            }).onfinish = () => f.remove()),
        );
      }, landed);
    } catch (e) {
      setCreate({
        status: "error",
        error:
          e instanceof Error && e.message
            ? e.message
            : "Couldn’t make the link. Try again.",
      });
    }
  };

  const reset = () => {
    setItems([]);
    setLink(null);
    setCreate({ status: "idle" });
    setPassword("");
    setLock(false);
  };

  const shared = link?.files ?? [];
  const sharedSize = shared.reduce((n, i) => n + i.file.size, 0);

  return (
    <section
      ref={sectionRef}
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[420px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
      onDragEnter={(e) => {
        if (link || !e.dataTransfer.types.includes("Files")) return;
        e.preventDefault();
        depth.current++;
        setOver(e.dataTransfer.items.length || 1);
      }}
      onDragOver={(e) => {
        if (link || !e.dataTransfer.types.includes("Files")) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = "copy";
      }}
      onDragLeave={() => {
        depth.current = Math.max(0, depth.current - 1);
        if (!depth.current) setOver(0);
      }}
      onDrop={(e) => {
        if (link) return;
        e.preventDefault();
        depth.current = 0;
        setOver(0);
        add(e.dataTransfer.files);
      }}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 420px)" }}
      />
      <div className="@container w-full">
        <input
          ref={inputRef}
          type="file"
          multiple
          accept={accept}
          className="sr-only"
          tabIndex={-1}
          aria-hidden="true"
          onChange={(e) => {
            if (e.target.files?.length) add(e.target.files);
            e.target.value = "";
          }}
        />

        {/* The one lit surface: the drop area, which becomes the link. */}
        <div
          ref={panelRef}
          className="rounded-[22px] p-2 text-primary-foreground"
          style={LIT}
        >
          <Faces active={link ? 1 : 0} reduced={reduced} ready={ready}>
            <div
              className="flex min-h-[132px] flex-col items-center justify-center rounded-[16px] px-4 py-5 text-center"
              style={{
                boxShadow: `inset 0 0 0 1px ${over ? "var(--primary-foreground)" : mix("var(--primary-foreground)", 30)}`,
                background: over
                  ? mix("var(--primary-foreground)", 10)
                  : "transparent",
                transform: over && !reduced ? "scale(0.985)" : "none",
                transition: reduced
                  ? "none"
                  : `box-shadow 200ms, background-color 200ms, transform 320ms ${EASE}`,
              }}
            >
              <span
                className="flex size-10 items-center justify-center rounded-full"
                style={{ background: mix("var(--primary-foreground)", 14) }}
              >
                <Upload
                  aria-hidden="true"
                  className="size-[18px]"
                  style={{
                    transform: over && !reduced ? "translateY(-2px)" : "none",
                    transition: `transform 300ms ${EASE}`,
                  }}
                />
              </span>
              <h2
                id={`${baseId}-title`}
                className="mt-2.5 text-[15px] font-medium tracking-[-0.01em]"
              >
                <TextMorph>
                  {over
                    ? `Release to add ${over === 1 ? "it" : over}`
                    : items.length
                      ? "Add more files"
                      : "Drop files to share"}
                </TextMorph>
              </h2>
              <p className="mt-1 text-[12.5px] text-primary-foreground/70">
                or{" "}
                <button
                  type="button"
                  onClick={() => inputRef.current?.click()}
                  className={`cursor-pointer rounded-full font-medium text-primary-foreground underline decoration-primary-foreground/40 underline-offset-[3px] hover:decoration-primary-foreground ${INTERACTION_FOCUS}`}
                >
                  choose files
                </button>
                {maxSize ? ` · up to ${size(maxSize)} each` : ""}
              </p>
            </div>

            <div className="p-2.5">
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0">
                  <p className="text-[12.5px] text-primary-foreground/70">
                    Ready to share
                  </p>
                  <p className="mt-0.5 text-[17px] font-medium leading-tight tracking-[-0.02em]">
                    {shared.length} {shared.length === 1 ? "file" : "files"} ·{" "}
                    {size(sharedSize)}
                  </p>
                  <p className="mt-1 inline-flex items-center gap-1.5 text-[12.5px] text-primary-foreground/75">
                    {lock && <Lock aria-hidden="true" className="size-3" />}
                    Expires in {expires} {expires === 1 ? "day" : "days"}
                    {lock ? " · password" : ""}
                  </p>
                </div>
                {/* The files, fanned as the stack they folded into. */}
                <span
                  aria-hidden="true"
                  className="relative mr-2 mt-1 h-12 w-14 shrink-0"
                >
                  {shared.slice(0, 3).map((it, i, all) => {
                    const turn = (i - (all.length - 1) / 2) * 10;
                    return (
                      // The fan is on the outer layer, the pop on the inner one, so the keyframe never undoes the turn.
                      <span
                        key={it.id}
                        className="absolute left-2 top-0"
                        style={{
                          transform: `rotate(${turn}deg) translateX(${turn * 0.6}px)`,
                        }}
                      >
                        <span
                          className={`flex h-12 w-10 items-end justify-center rounded-[8px] pb-1 font-mono text-[8.5px] font-medium ${link?.flown ? "" : "motion-safe:animate-[ui-pop-in_420ms_cubic-bezier(0.34,1.36,0.64,1)_both]"}`}
                          style={{
                            ...tint(extOf(it.file.name)),
                            animationDelay: `${i * 70}ms`,
                            boxShadow: `0 0 0 1px ${mix("var(--primary)", 60)}`,
                          }}
                        >
                          {extOf(it.file.name)}
                        </span>
                      </span>
                    );
                  })}
                </span>
              </div>
              <div
                className="mt-3 flex h-10 items-center gap-2 rounded-full pl-4 pr-1"
                style={{
                  background: mix("black", 14),
                  boxShadow: `inset 0 1px 0 ${mix("black", 12)}, inset 0 0 0 1px ${mix("var(--primary-foreground)", 10)}`,
                }}
              >
                <span className="min-w-0 flex-1 truncate font-mono text-[12.5px] text-primary-foreground/90">
                  {link?.url.replace(/^https?:\/\//, "")}
                </span>
                {link && (
                  <CopyButton
                    text={link.url}
                    label="Copy link"
                    copiedLabel="Copied"
                    showLabel
                    size="sm"
                    variant="secondary"
                    style={{
                      background: "var(--primary-foreground)",
                      color: "var(--primary)",
                    }}
                    className="shrink-0 hover:opacity-90"
                  />
                )}
              </div>
              <button
                type="button"
                onClick={reset}
                className={`mt-2 h-8 cursor-pointer rounded-full px-1 text-[12.5px] text-primary-foreground/80 hover:text-primary-foreground ${INTERACTION_FOCUS}`}
              >
                Share more files
              </button>
            </div>
          </Faces>
        </div>

        {/* Flat: the files on their way up, and how the link should work. */}
        <div
          className="grid grid-cols-1"
          style={{
            gridTemplateRows: link || !items.length ? "0fr" : "1fr",
            opacity: link || !items.length ? 0 : 1,
            transition: reduced
              ? "opacity 160ms"
              : `grid-template-rows 460ms ${EASE}, opacity 300ms ${EASE}`,
          }}
        >
          <div
            className={`min-h-0 ${flying ? "overflow-visible" : "overflow-clip"}`}
            inert={Boolean(link) || !items.length || undefined}
          >
            <div className="px-2 pt-2.5">
              <div className="flex items-baseline justify-between px-1 text-[12px] text-muted-foreground">
                <span>
                  <NumberRoll value={items.length} duration={500} />{" "}
                  {items.length === 1 ? "file" : "files"} · {size(total)}
                </span>
                <span className="tabular-nums">
                  {uploading ? (
                    <>
                      <NumberRoll
                        value={total ? Math.floor((sent / total) * 100) : 0}
                        duration={400}
                      />
                      % sent
                    </>
                  ) : doneItems.length ? (
                    "All sent"
                  ) : (
                    ""
                  )}
                </span>
              </div>
              <ul ref={listRef} className="mt-1.5">
                {items.map((it) => (
                  <li
                    key={it.id}
                    data-file
                    className="relative flex h-12 items-center gap-2.5 border-t border-border/70 px-1 first:border-t-0"
                  >
                    <span
                      aria-hidden="true"
                      data-tile
                      className="flex h-8 w-7 shrink-0 items-end justify-center rounded-[6px] pb-0.5 font-mono text-[8px] font-medium"
                      style={tint(extOf(it.file.name))}
                    >
                      {extOf(it.file.name)}
                    </span>
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-[13.5px] text-foreground">
                        {it.file.name}
                      </span>
                      <span
                        className={`block text-[11.5px] tabular-nums ${it.status === "error" ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
                      >
                        {size(it.file.size)} ·{" "}
                        {it.status === "error" ? (
                          it.error
                        ) : it.status === "done" ? (
                          <TextMorph>Uploaded</TextMorph>
                        ) : (
                          <>
                            <NumberRoll
                              value={Math.floor(it.progress * 100)}
                              duration={300}
                            />
                            %
                          </>
                        )}
                      </span>
                    </span>
                    {it.status === "error" &&
                      !(maxSize && it.file.size > maxSize) && (
                        <button
                          type="button"
                          aria-label={`Retry ${it.file.name}`}
                          onClick={() => upload(it)}
                          className={`flex size-7 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                        >
                          <RotateCw aria-hidden="true" className="size-3.5" />
                        </button>
                      )}
                    <button
                      type="button"
                      aria-label={`Remove ${it.file.name}`}
                      disabled={busy}
                      onClick={() => remove(it)}
                      className={`-mr-1 flex size-7 cursor-pointer items-center justify-center rounded-full text-muted-foreground hover:bg-accent hover:text-foreground disabled:opacity-40 ${INTERACTION_PRESS} ${INTERACTION_FOCUS}`}
                    >
                      <X aria-hidden="true" className="size-3.5" />
                    </button>
                    {/* The thin line that fills as the file goes up. */}
                    <span
                      aria-hidden="true"
                      className={`absolute inset-x-1 bottom-0 h-px origin-left ${it.status === "error" ? "bg-red-500" : "bg-primary"}`}
                      style={{
                        opacity: it.status === "done" ? 0 : 0.8,
                        transform: `scaleX(${it.status === "error" ? 1 : it.progress})`,
                        transition: reduced
                          ? "opacity 200ms"
                          : `transform 300ms ${EASE}, opacity 400ms ${EASE} 200ms`,
                      }}
                    />
                  </li>
                ))}
              </ul>

              <div className="mt-2.5 flex flex-col gap-2.5 border-t border-border pt-3 @[360px]:flex-row @[360px]:items-center @[360px]:justify-between">
                <SegmentedControl
                  label="Link expires after"
                  size="sm"
                  value={String(expires)}
                  onValueChange={(v) => setExpires(Number(v))}
                  options={expiries.map((d) => ({
                    value: String(d),
                    label: d === 1 ? "1 day" : `${d} days`,
                  }))}
                />
                <Switch
                  size="sm"
                  label="Password"
                  checked={lock}
                  onCheckedChange={(v) => setLock(v)}
                />
              </div>
              <div
                className="grid grid-cols-1"
                style={{
                  gridTemplateRows: lock ? "1fr" : "0fr",
                  transition: reduced
                    ? "none"
                    : `grid-template-rows 360ms ${EASE}`,
                }}
              >
                <div
                  className="min-h-0 overflow-clip"
                  inert={!lock || undefined}
                >
                  <Input
                    type="password"
                    aria-label="Password for the link"
                    placeholder="Password for the link"
                    autoComplete="new-password"
                    value={password}
                    onValueChange={setPassword}
                    className="pt-2.5"
                  />
                </div>
              </div>
              <StatusButton
                status={create.status}
                labels={{
                  idle: uploading ? "Uploading…" : "Create link",
                  pending: "Creating link",
                  success: "Link ready",
                  error: "Try again",
                }}
                disabled={!canCreate && create.status === "idle"}
                onClick={() => void createLink()}
                className="mt-3 h-11 w-full text-[14.5px] disabled:opacity-50"
                style={create.status === "error" ? undefined : ACTION}
              />
              <p
                role={create.error ? "alert" : undefined}
                className={`mt-1.5 pb-1 text-center text-[12px] ${create.error ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
              >
                {create.error ??
                  (lock && !password.trim()
                    ? "Add a password, or switch it off."
                    : "Anyone with the link can download.")}
              </p>
            </div>
          </div>
        </div>

        <span className="sr-only" role="status">
          {said}
        </span>
      </div>
    </section>
  );
}

export default FileShare;

"use client";

import * as React from "react";
import { Copy } from "lucide-react";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * COPY BUTTON: copies, and says so the moment you press
 *
 *   idle     the copy icon (and "Copy" when labelled)
 *   copied   flips on the press itself, not after the clipboard
 *            answers: the icon blurs out, a check draws itself,
 *            "Copy" morphs to "Copied" and the pill eases wider
 *   error    if the clipboard refuses, the check gives way to an
 *            alert, the label says "Failed" and the button shakes
 *
 * Pressing again while copied copies again and restarts the timer.
 * A status region outside the button tells screen readers.
 * ───────────────────────────────────────────────────────── */

export type CopyState = "idle" | "copied" | "error";

export interface CopyButtonProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "children"
> {
  /** The text to copy. */
  text: string;
  /** Label while idle; also the icon-only button's accessible name. */
  label?: string;
  /** Label once copied. */
  copiedLabel?: string;
  /** Label if the clipboard refuses. */
  errorLabel?: string;
  /** Show the label beside the icon. Defaults to false (icon only). */
  showLabel?: boolean;
  /** How long "Copied" stays before it returns to idle (ms). */
  timeoutMs?: number;
  variant?: "secondary" | "outline" | "ghost";
  /** xs 24px, sm 28px, md 36px tall. */
  size?: "xs" | "sm" | "md";
  onCopySuccess?: (text: string) => void;
  onCopyError?: (error: unknown) => void;
}

const SIZES = {
  xs: {
    square: "size-6",
    pill: "h-6 pl-2 pr-2.5 text-[12px]",
    icon: 12,
    gap: 5,
  },
  sm: {
    square: "size-7",
    pill: "h-7 pl-2.5 pr-3 text-[12px]",
    icon: 13,
    gap: 6,
  },
  md: {
    square: "size-9",
    pill: "h-9 pl-3.5 pr-4 text-[13px]",
    icon: 15,
    gap: 7,
  },
};

const TONES = {
  secondary:
    "bg-card text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent",
  outline:
    "bg-transparent text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent",
  ghost:
    "bg-transparent text-muted-foreground hover:bg-accent hover:text-foreground",
};

const ERROR_TONE =
  "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400";

function writeClipboard(text: string): Promise<void> {
  if (navigator.clipboard?.writeText)
    return navigator.clipboard.writeText(text);
  // Older browsers and plain-http pages: the selection fallback.
  return new Promise((resolve, reject) => {
    const area = document.createElement("textarea");
    area.value = text;
    area.setAttribute("readonly", "");
    area.style.cssText =
      "position:fixed;top:0;left:0;opacity:0;pointer-events:none";
    document.body.appendChild(area);
    area.select();
    const ok = document.execCommand("copy");
    area.remove();
    if (ok) resolve();
    else reject(new Error("Copy was refused"));
  });
}

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-full">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          // Draws on the way in; on the way out it stays whole until its layer has faded.
          transition: reduced
            ? "none"
            : drawn
              ? `stroke-dashoffset 360ms ${EASE_OUT} 70ms`
              : "stroke-dashoffset 0ms linear 300ms",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-full">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function CopyButton({
  text,
  label = "Copy",
  copiedLabel = "Copied",
  errorLabel = "Failed",
  showLabel = false,
  timeoutMs = 2000,
  variant = "ghost",
  size = "sm",
  onCopySuccess,
  onCopyError,
  className = "",
  disabled,
  onClick,
  ...props
}: CopyButtonProps) {
  const reduced = useInteractionReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const [state, setState] = React.useState<CopyState>("idle");
  // Bumped on every copy so a second press restarts the timer.
  const [stamp, setStamp] = React.useState(0);

  React.useEffect(() => {
    if (state === "idle") return;
    const timer = window.setTimeout(() => setState("idle"), timeoutMs);
    return () => window.clearTimeout(timer);
  }, [state, stamp, timeoutMs]);

  React.useEffect(() => {
    if (state !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [state, stamp, reduced]);

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    onClick?.(e);
    if (e.defaultPrevented || disabled || !text) return;
    // Optimistic: the feedback lands on the press, the clipboard catches up.
    setState("copied");
    setStamp((n) => n + 1);
    writeClipboard(text).then(
      () => onCopySuccess?.(text),
      (error: unknown) => {
        setState("error");
        setStamp((n) => n + 1);
        onCopyError?.(error);
      },
    );
  };

  const s = SIZES[size];
  const current =
    state === "copied" ? copiedLabel : state === "error" ? errorLabel : label;

  return (
    <>
      <button
        ref={ref}
        type="button"
        disabled={disabled}
        onClick={handleClick}
        aria-label={showLabel ? undefined : label}
        data-state={state}
        className={`relative inline-flex shrink-0 select-none items-center justify-center whitespace-nowrap rounded-full font-medium cursor-pointer disabled:cursor-default disabled:opacity-45 ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${
          state === "error" ? ERROR_TONE : TONES[variant]
        } ${showLabel ? s.pill : s.square} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className="relative shrink-0"
          style={{ width: s.icon, height: s.icon }}
        >
          <span
            className="absolute inset-0 flex items-center justify-center"
            style={interactionIcon(state === "idle", reduced)}
          >
            <Copy size={s.icon} strokeWidth={1.75} />
          </span>
          <span
            className="absolute inset-0 text-emerald-600 dark:text-emerald-400"
            style={interactionIcon(state === "copied", reduced)}
          >
            <Check drawn={state === "copied"} reduced={reduced} />
          </span>
          <span
            className="absolute inset-0"
            style={interactionIcon(state === "error", reduced)}
          >
            <Alert />
          </span>
        </span>
        {showLabel && (
          <TextMorph style={{ marginLeft: s.gap }}>{current}</TextMorph>
        )}
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span role="status" className="sr-only">
        {state === "idle" ? "" : current}
      </span>
    </>
  );
}

export default CopyButton;

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * FACES: the states of one surface, in the same place
 *
 * The active face is in flow; the others are laid over it, faded
 * and nudged aside (faces before it to the left, faces after it to
 * the right), so switching reads as the surface turning to its
 * next side. The height eases between the faces' measured heights,
 * so nothing around it jumps. Used by the blocks (the wallet's
 * activity and keypad, a pricing card and its checkout, a booking's
 * times, details and confirmation).
 * ───────────────────────────────────────────────────────── */

const EASE = "cubic-bezier(0.16,1,0.3,1)";
export const FACES_MORPH = 460;

export function Faces({
  active,
  reduced,
  ready,
  className = "",
  children,
}: {
  active: number;
  reduced: boolean;
  /** False until the first paint, so the faces don't animate into place on mount. */
  ready: boolean;
  className?: string;
  children: React.ReactNode[];
}) {
  const refs = React.useRef<(HTMLDivElement | null)[]>([]);
  const [heights, setHeights] = React.useState<number[] | null>(null);
  const count = children.length;

  React.useLayoutEffect(() => {
    const els = refs.current.slice(0, count);
    const observer = new ResizeObserver(() => {
      const next = els.map((el) => el?.offsetHeight ?? 0);
      setHeights((p) =>
        p && p.length === next.length && p.every((h, i) => h === next[i])
          ? p
          : next,
      );
    });
    els.forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [count]);

  const face = (i: number): React.CSSProperties => {
    const on = i === active;
    return {
      opacity: on ? 1 : 0,
      transform:
        on || reduced ? "none" : `translateX(${i < active ? -18 : 18}px)`,
      filter: on || reduced ? "none" : "blur(4px)",
      transition: !ready
        ? "none"
        : reduced
          ? "opacity 160ms ease-out"
          : on
            ? `opacity 320ms ${EASE} 90ms, transform ${FACES_MORPH}ms ${EASE}, filter 320ms ${EASE} 90ms`
            : `opacity 140ms ease-out, transform ${FACES_MORPH}ms ${EASE}, filter 200ms ease-out`,
    };
  };

  return (
    <div
      className={`relative overflow-clip ${className}`}
      style={{
        height: heights ? heights[active] : undefined,
        transition:
          ready && !reduced ? `height ${FACES_MORPH}ms ${EASE}` : "none",
      }}
    >
      {children.map((child, i) => (
        <div
          key={i}
          ref={(el) => {
            refs.current[i] = el;
          }}
          inert={active !== i || undefined}
          aria-hidden={active !== i || undefined}
          className={
            active === i
              ? "relative"
              : "pointer-events-none absolute inset-x-0 top-0"
          }
          style={face(i)}
        >
          {child}
        </div>
      ))}
    </div>
  );
}

"use client";

import * as React from "react";
import {
  Field,
  fieldSurface,
  setNativeValue,
  useFieldIds,
  useShake,
  type FieldSize,
} from "./imported-field";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * INPUT: a one-line field
 *
 *   rest     a thin line pill; hover darkens the line
 *   focus    the line turns to the ring with a 3px halo
 *   typing   a clear button folds in once there is text and
 *            folds away when it's gone (it hands focus back)
 *   error    the line turns red, the hint gives way to the
 *            error and the field shakes once
 * ───────────────────────────────────────────────────────── */

export interface InputProps extends Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "size"
> {
  label?: React.ReactNode;
  hint?: React.ReactNode;
  /** Shows red and replaces the hint. */
  error?: React.ReactNode;
  /** An icon or text before the value. */
  leading?: React.ReactNode;
  /** An icon, text or button after the value. */
  trailing?: React.ReactNode;
  /** A button that empties the field once it has text. */
  clearable?: boolean;
  /** 28px or 36px tall. */
  size?: FieldSize;
  /** Called with the new text on every change. */
  onValueChange?: (value: string) => void;
  ref?: React.Ref<HTMLInputElement>;
  /** Class for the outer column. */
  className?: string;
  /** Class for the input element itself. */
  inputClassName?: string;
}

function ClearIcon() {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M4.5 4.5l7 7M11.5 4.5l-7 7"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function Input({
  label,
  hint,
  error,
  leading,
  trailing,
  clearable,
  size = "md",
  onValueChange,
  ref,
  id,
  className = "",
  inputClassName = "",
  value,
  defaultValue,
  onChange,
  disabled,
  required,
  ...props
}: InputProps) {
  const reduced = useInteractionReducedMotion();
  const ids = useFieldIds(id);
  const inner = React.useRef<HTMLInputElement>(null);
  const [text, setText] = React.useState(String(defaultValue ?? ""));
  const current = value !== undefined ? String(value) : text;
  const shakeRef = useShake<HTMLDivElement>(!!error);
  const sm = size === "sm";
  const showClear = !!clearable && current.length > 0 && !disabled;

  const setRefs = (el: HTMLInputElement | null) => {
    inner.current = el;
    if (typeof ref === "function") ref(el);
    else if (ref)
      (ref as React.RefObject<HTMLInputElement | null>).current = el;
  };

  const describedBy =
    [hint && !error ? ids.hint : null, error ? ids.error : null]
      .filter(Boolean)
      .join(" ") || undefined;

  return (
    <Field
      id={ids.id}
      label={label}
      hint={hint}
      error={error}
      required={required}
      className={className}
    >
      <div
        ref={shakeRef}
        className={`${fieldSurface({ invalid: !!error, disabled })} ${sm ? "h-7 text-[16px] sm:text-[12.5px]" : "h-9 text-[16px] sm:text-[13.5px]"}`}
      >
        {leading && (
          <span
            className={`flex shrink-0 items-center text-muted-foreground ${sm ? "pl-2.5" : "pl-3.5"} [&_svg]:size-3.5`}
          >
            {leading}
          </span>
        )}
        <input
          ref={setRefs}
          id={ids.id}
          value={value}
          defaultValue={defaultValue}
          disabled={disabled}
          required={required}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
          onChange={(e) => {
            if (value === undefined) setText(e.target.value);
            onChange?.(e);
            onValueChange?.(e.target.value);
          }}
          className={`h-full min-w-0 flex-1 bg-transparent outline-none placeholder:text-muted-foreground/70 ${leading ? "pl-2" : sm ? "pl-3" : "pl-4"} ${trailing || clearable ? "pr-1" : sm ? "pr-3" : "pr-4"} ${inputClassName}`}
          {...props}
        />
        {clearable && (
          // The clear button folds its own width open, so the text never jumps.
          <span
            className="grid shrink-0"
            style={{
              gridTemplateColumns: showClear ? "1fr" : "0fr",
              transition: reduced
                ? "none"
                : `grid-template-columns 320ms ${EASE_OUT}`,
            }}
          >
            <span className="min-w-0 overflow-hidden">
              <button
                type="button"
                tabIndex={showClear ? 0 : -1}
                aria-hidden={!showClear}
                aria-label="Clear"
                onClick={() => {
                  if (!inner.current) return;
                  setNativeValue(inner.current, "");
                  inner.current.focus();
                }}
                className={`mr-1 flex items-center justify-center rounded-full text-muted-foreground cursor-pointer hover:bg-accent hover:text-foreground ${sm ? "size-5" : "size-7"} ${INTERACTION_FOCUS}`}
                style={interactionIcon(showClear, reduced)}
              >
                <ClearIcon />
              </button>
            </span>
          </span>
        )}
        {trailing && (
          <span
            className={`flex shrink-0 items-center text-muted-foreground ${sm ? "pr-1" : "pr-1.5"} [&_svg]:size-3.5`}
          >
            {trailing}
          </span>
        )}
      </div>
    </Field>
  );
}

export default Input;

"use client";

import * as React from "react";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * FIELD: the column every text control sits in
 *
 *   label    above, with an optional aside on the right (a count)
 *   hint     under the control while all is well
 *   error    takes the hint's place: the hint folds away, the
 *            error rises in out of a blur, the control shakes once
 *
 * Shared by input, textarea, password, search and select so the
 * whole family has one surface, one focus ring and one error.
 * ───────────────────────────────────────────────────────── */

export interface FieldProps {
  id: string;
  label?: React.ReactNode;
  /** Right side of the label row, e.g. a character count. */
  aside?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  required?: boolean;
  className?: string;
  children: React.ReactNode;
}

export type FieldSize = "sm" | "md";

/** The surface of a text control: a thin line that darkens on hover and turns to the ring on focus. */
export function fieldSurface({
  invalid,
  disabled,
  round = true,
}: {
  invalid?: boolean;
  disabled?: boolean;
  round?: boolean;
}) {
  const ring = invalid
    ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_55%,transparent)] focus-within:shadow-[inset_0_0_0_1px_var(--color-red-500),0_0_0_3px_color-mix(in_oklab,var(--color-red-500)_14%,transparent)]"
    : "shadow-[inset_0_0_0_1px_var(--border)] [&:not(:focus-within)]:hover:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_24%,var(--border))] focus-within:shadow-[inset_0_0_0_1px_var(--ring),0_0_0_3px_color-mix(in_oklab,var(--ring)_16%,transparent)]";
  return `relative flex w-full items-center bg-background text-foreground transition-[box-shadow,background-color,opacity] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] ${round ? "rounded-full" : "rounded-[14px]"} ${ring} ${
    disabled ? "pointer-events-none opacity-50" : ""
  }`;
}

/** ids for the control's label, hint and error. */
export function useFieldIds(id?: string) {
  const auto = React.useId();
  const base = id ?? auto;
  return { id: base, hint: `${base}-hint`, error: `${base}-error` };
}

/** One short shake whenever `on` turns true (an error arrives). */
export function useShake<T extends HTMLElement>(on: boolean) {
  const ref = React.useRef<T>(null);
  const reduced = useInteractionReducedMotion();
  React.useEffect(() => {
    if (!on || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [on, reduced]);
  return ref;
}

/** Sets a native input's value so React's onChange still fires (clear buttons, pickers). */
export function setNativeValue(
  el: HTMLInputElement | HTMLTextAreaElement,
  value: string,
) {
  const proto =
    el instanceof HTMLTextAreaElement
      ? HTMLTextAreaElement.prototype
      : HTMLInputElement.prototype;
  Object.getOwnPropertyDescriptor(proto, "value")?.set?.call(el, value);
  el.dispatchEvent(new Event("input", { bubbles: true }));
}

/** A line under the control that folds open and closed; keeps its last words while closing. */
function Line({
  show,
  children,
  id,
  tone,
  reduced,
}: {
  show: boolean;
  children: React.ReactNode;
  id: string;
  tone: string;
  reduced: boolean;
}) {
  const [kept, setKept] = React.useState(children);
  if (show && children !== kept) setKept(children);
  return (
    <div
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        transition: reduced ? "none" : `grid-template-rows 320ms ${EASE_OUT}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">
        <p
          id={id}
          className={`pt-1.5 pl-3 text-[12.5px] leading-snug ${tone}`}
          style={{
            opacity: show ? 1 : 0,
            filter: show ? "blur(0px)" : "blur(4px)",
            transform: show ? "none" : "translateY(-4px)",
            transition: reduced
              ? "none"
              : show
                ? `opacity 280ms ${EASE_OUT} 60ms, filter 280ms ${EASE_OUT} 60ms, transform 380ms ${EASE_OUT}`
                : `opacity 140ms ${EASE_OUT}, filter 140ms ${EASE_OUT}, transform 200ms ${EASE_OUT}`,
          }}
        >
          {show ? children : kept}
        </p>
      </div>
    </div>
  );
}

export function Field({
  id,
  label,
  aside,
  hint,
  error,
  required,
  className = "",
  children,
}: FieldProps) {
  const reduced = useInteractionReducedMotion();
  const ids = { hint: `${id}-hint`, error: `${id}-error` };
  return (
    <div className={`flex w-full flex-col ${className}`}>
      {(label || aside) && (
        <div className="flex items-baseline justify-between gap-3 px-3 pb-1.5">
          {label && (
            <label
              htmlFor={id}
              className="text-[13px] font-medium text-foreground"
            >
              {label}
              {required && (
                <span
                  aria-hidden="true"
                  className="ml-0.5 text-muted-foreground"
                >
                  *
                </span>
              )}
            </label>
          )}
          {aside && (
            <span className="text-[12px] tabular-nums text-muted-foreground">
              {aside}
            </span>
          )}
        </div>
      )}
      {children}
      <Line
        show={!error && !!hint}
        id={ids.hint}
        tone="text-muted-foreground"
        reduced={reduced}
      >
        {hint}
      </Line>
      <Line
        show={!!error}
        id={ids.error}
        tone="text-red-600 dark:text-red-400"
        reduced={reduced}
      >
        {error}
      </Line>
    </div>
  );
}

export default Field;

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import {
  EASE_OUT,
  EASE_THROW,
  INTERACTION_FOCUS,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * SEGMENTED CONTROL: one of a few, side by side
 *
 *   pick     the thumb is thrown to the new segment with a slight
 *            overshoot while its width eases to the new label
 *   press    the thumb gives a little under the finger
 *   keys     a radiogroup: arrows move and select, Home/End jump;
 *            one tab stop for the whole control
 * ───────────────────────────────────────────────────────── */

export interface SegmentOption {
  value: string;
  label: React.ReactNode;
  icon?: React.ReactNode;
  /** Required when `label` isn't text (icon-only segments). */
  ariaLabel?: string;
  disabled?: boolean;
}

export interface SegmentedControlProps {
  options: SegmentOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Accessible name of the group. */
  label: string;
  /** 28px, 34px, or 40px tall (matches tactile sliders). */
  size?: "sm" | "md" | "lg";
  /** Stretch to the parent's width with equal segments. */
  block?: boolean;
  className?: string;
  /** Corner radius: "full" (pill, default) or "rounded" (concentric rounded container). */
  radius?: "full" | "rounded";
}

type Mark = { x: number; w: number };

export function SegmentedControl({
  options,
  value,
  defaultValue,
  onValueChange,
  label,
  size = "md",
  block,
  className = "",
  radius = "full",
}: SegmentedControlProps) {
  const reduced = useInteractionReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const [own, setOwn] = React.useState(defaultValue ?? options[0]?.value);
  const current = value !== undefined ? value : own;
  const [mark, setMark] = React.useState<Mark | null>(null);
  const [ready, setReady] = React.useState(false);
  const [pressing, setPressing] = React.useState(false);

  React.useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const measure = () => {
      const el = current
        ? root.querySelector<HTMLElement>(
            `[data-segment="${CSS.escape(current)}"]`,
          )
        : null;
      if (!el) return setMark(null);
      const next = { x: el.offsetLeft, w: el.offsetWidth };
      setMark((p) => (p && p.x === next.x && p.w === next.w ? p : next));
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(root);
    root.querySelectorAll("[data-segment]").forEach((el) => ro.observe(el));
    return () => ro.disconnect();
  }, [current, options]);

  React.useEffect(() => {
    if (!mark || ready) return;
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, [mark, ready]);

  const pick = (v: string) => {
    if (value === undefined) setOwn(v);
    onValueChange?.(v);
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const enabled = options.filter((o) => !o.disabled);
    const index = enabled.findIndex((o) => o.value === current);
    let next = -1;
    if (e.key === "ArrowRight" || e.key === "ArrowDown")
      next = (index + 1) % enabled.length;
    else if (e.key === "ArrowLeft" || e.key === "ArrowUp")
      next = (index - 1 + enabled.length) % enabled.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = enabled.length - 1;
    if (next < 0) return;
    e.preventDefault();
    const v = enabled[next].value;
    pick(v);
    rootRef.current
      ?.querySelector<HTMLElement>(`[data-segment="${CSS.escape(v)}"]`)
      ?.focus();
  };

  const isLg = size === "lg";
  const isSm = size === "sm";
  const isPill = radius === "full";

  // Concentric corner radius matching compact slider geometry
  const rootRadius = isPill
    ? "rounded-full"
    : isLg
      ? "rounded-[13px]"
      : isSm
        ? "rounded-[9px]"
        : "rounded-[11px]";
  const itemRadius = isPill
    ? "rounded-full"
    : isLg
      ? "rounded-[9px]"
      : isSm
        ? "rounded-[7px]"
        : "rounded-[9px]";

  // Proportional sizing: "md" is compact 34px, "lg" is 40px, "sm" is 28px
  const rootPadding = isLg ? "p-1" : "p-0.5";
  const rootHeight = isLg ? "h-10" : isSm ? "h-7" : "h-8.5";
  const indicatorInset = isLg ? "top-1 bottom-1" : "top-0.5 bottom-0.5";
  const itemHeightClass = isLg
    ? "h-8 px-3 text-[13px]"
    : isSm
      ? "h-6 px-2 text-[11.5px]"
      : "h-[30px] px-2.5 text-[12px]";

  return (
    <div
      ref={rootRef}
      role="radiogroup"
      aria-label={label}
      onKeyDown={onKeyDown}
      className={`relative isolate select-none items-center ${rootHeight} ${rootRadius} ${rootPadding} border border-black/[0.04] dark:border-white/[0.06] bg-[#f4f4f6] dark:bg-zinc-900/50 ${
        block ? "flex w-full" : "inline-flex"
      } ${className}`}
    >
      <span
        aria-hidden="true"
        className={`pointer-events-none absolute left-0 ${indicatorInset} ${itemRadius} bg-white dark:bg-zinc-800 border border-black/[0.05] dark:border-white/[0.1] shadow-[0_1px_2px_rgba(0,0,0,0.04)]`}
        style={{
          transform: `translate3d(${mark?.x ?? 0}px, 0, 0) scale(${pressing && !reduced ? 0.97 : 1})`,
          width: mark?.w ?? 0,
          opacity: mark ? 1 : 0,
          transition:
            reduced || !ready
              ? "none"
              : `transform 440ms ${EASE_THROW}, width 400ms ${EASE_OUT}, opacity 200ms ${EASE_OUT}`,
        }}
      />
      {options.map((option) => {
        const on = option.value === current;
        return (
          <button
            key={option.value}
            type="button"
            role="radio"
            aria-checked={on}
            aria-label={option.ariaLabel}
            data-segment={option.value}
            disabled={option.disabled}
            tabIndex={on ? 0 : -1}
            onClick={() => pick(option.value)}
            onPointerDown={() => on && setPressing(true)}
            onPointerUp={() => setPressing(false)}
            onPointerLeave={() => setPressing(false)}
            className={`relative z-10 inline-flex items-center justify-center gap-1.5 whitespace-nowrap ${itemRadius} font-medium cursor-pointer transition-colors duration-200 disabled:cursor-default disabled:opacity-40 [&_svg]:size-3.5 ${itemHeightClass} ${
              block ? "flex-1" : ""
            } ${on ? "text-zinc-950 font-semibold dark:text-white" : "text-zinc-600 hover:text-zinc-950 dark:text-zinc-400 dark:hover:text-zinc-100"} ${INTERACTION_FOCUS}`}
          >
            {option.icon}
            {option.label}
          </button>
        );
      })}
    </div>
  );
}

export default SegmentedControl;

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";
import {
  EASE_OUT,
  EASE_THROW,
  INTERACTION_FOCUS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * SWITCH: on and off, with weight
 *
 *   press    the thumb stretches toward the side it will go
 *   flip     it's thrown across with a slight overshoot while the
 *            track fills; the fill and thumb move as one
 *   async    if onCheckedChange returns a promise, the switch
 *            flips at once and the thumb spins until it settles;
 *            a rejection throws it back and shakes the track
 * ───────────────────────────────────────────────────────── */

export interface SwitchProps extends Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "onChange" | "value"
> {
  checked?: boolean;
  defaultChecked?: boolean;
  /** Return a promise to show the pending thumb; throw to put it back. */
  onCheckedChange?: (checked: boolean) => void | Promise<unknown>;
  label?: React.ReactNode;
  description?: React.ReactNode;
  /** 16px or 20px tall. */
  size?: "sm" | "md";
  /** Put the label before the switch (settings rows). */
  labelPosition?: "start" | "end";
  ref?: React.Ref<HTMLButtonElement>;
}

const SIZES = { sm: { w: 28, h: 16, pad: 2 }, md: { w: 36, h: 20, pad: 2 } };

export function Switch({
  checked,
  defaultChecked = false,
  onCheckedChange,
  label,
  description,
  size = "md",
  labelPosition = "end",
  disabled,
  className = "",
  id,
  ref,
  ...props
}: SwitchProps) {
  const reduced = useInteractionReducedMotion();
  const auto = React.useId();
  const switchId = id ?? auto;
  const track = React.useRef<HTMLSpanElement>(null);
  const [own, setOwn] = React.useState(defaultChecked);
  const [optimistic, setOptimistic] = React.useState<boolean | null>(null);
  const [pressed, setPressed] = React.useState(false);
  const on = optimistic ?? (checked !== undefined ? checked : own);
  const pending = optimistic !== null;
  const s = SIZES[size];
  const thumb = s.h - s.pad * 2;
  const travel = s.w - thumb - s.pad * 2;
  const stretch = pressed && !reduced ? 4 : 0;

  const toggle = () => {
    if (disabled || pending) return;
    const next = !on;
    const result = onCheckedChange?.(next);
    if (result && typeof (result as Promise<unknown>).then === "function") {
      setOptimistic(next);
      (result as Promise<unknown>).then(
        () => {
          if (checked === undefined) setOwn(next);
          setOptimistic(null);
        },
        () => {
          setOptimistic(null);
          if (!reduced)
            track.current?.animate(
              [
                { transform: "none" },
                { transform: "translateX(-3px)" },
                { transform: "translateX(3px)" },
                { transform: "none" },
              ],
              { duration: 320, easing: "ease-out" },
            );
        },
      );
    } else if (checked === undefined) setOwn(next);
  };

  const control = (
    <button
      ref={ref}
      id={switchId}
      type="button"
      role="switch"
      aria-checked={on}
      aria-busy={pending || undefined}
      disabled={disabled}
      onClick={toggle}
      onPointerDown={() => setPressed(true)}
      onPointerUp={() => setPressed(false)}
      onPointerLeave={() => setPressed(false)}
      onBlur={() => setPressed(false)}
      className={`relative inline-flex shrink-0 rounded-full cursor-pointer disabled:cursor-default disabled:opacity-50 ${INTERACTION_FOCUS}`}
      style={{ width: s.w, height: s.h }}
      {...props}
    >
      <span
        ref={track}
        className="absolute inset-0 overflow-hidden rounded-full bg-[color-mix(in_oklab,var(--foreground)_12%,var(--muted))] shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_10%,transparent)]"
      >
        <span
          className="absolute inset-0 rounded-full bg-primary"
          style={{
            opacity: on ? 1 : 0,
            transition: reduced ? "none" : `opacity 260ms ${EASE_OUT}`,
          }}
        />
      </span>
      <span
        className="absolute rounded-full bg-background shadow-[0_0_0_1px_color-mix(in_oklab,var(--foreground)_10%,transparent)]"
        style={{
          top: s.pad,
          left: s.pad,
          height: thumb,
          width: thumb + stretch,
          // Stretching toward where it's going: grow from the far edge when on.
          transform: `translateX(${on ? travel - stretch : 0}px)`,
          transition: reduced
            ? "none"
            : `transform 420ms ${EASE_THROW}, width 260ms ${EASE_OUT}`,
        }}
      >
        <span
          className="absolute inset-0 flex items-center justify-center text-primary"
          style={interactionIcon(pending, reduced)}
        >
          <span
            className={`size-[60%] rounded-full border-[1.5px] border-current border-t-transparent ${pending ? "animate-spin" : ""}`}
          />
        </span>
      </span>
    </button>
  );

  if (!label && !description)
    return <span className={className}>{control}</span>;

  return (
    <div
      className={`flex items-start gap-3 ${labelPosition === "start" ? "flex-row-reverse justify-between" : ""} ${className}`}
    >
      <span className="mt-0.5">{control}</span>
      <label
        htmlFor={switchId}
        className={`flex min-w-0 flex-col gap-0.5 ${disabled ? "opacity-50" : "cursor-pointer"}`}
      >
        {label && (
          <span className="text-[13.5px] font-medium leading-5 text-foreground">
            {label}
          </span>
        )}
        {description && (
          <span className="text-[12.5px] leading-snug text-muted-foreground">
            {description}
          </span>
        )}
      </label>
    </div>
  );
}

export default Switch;

